/*
 * O corpo do card "Atribuir tópico": a conta do assistente de IA, à parte da
 * conta do sistema. Atribuído a ela, o tópico ganha uma resposta da IA do tema.
 */
import app from 'flarum/admin/app';
import Button from 'flarum/common/components/Button';
import Avatar from 'flarum/common/components/Avatar';
import { AdminComponent, trans } from '../util';
const KEY = 'ramon-canela.admin.settings.gaps';
const SETTING = 'canela.assign_bot_user_id';
export default class AssistantCard extends AdminComponent {
  loading = false;
  created = null;
  view() {
    const user = this.created || app.forum.attribute('canelaAssistant');
    if (!user) {
      return m("div", {
        className: "CanelaSystemAdmin"
      }, m("p", {
        className: "helpText"
      }, trans(`${KEY}.assign_bot_missing`)), m(Button, {
        className: "Button",
        icon: "fas fa-robot",
        loading: this.loading,
        onclick: () => this.create()
      }, trans(`${KEY}.assign_bot_create`)));
    }
    const avatarUser = {
      avatarUrl: () => user.avatarUrl,
      displayName: () => user.displayName,
      username: () => user.username,
      color: () => ''
    };
    return m("div", {
      className: "CanelaSystemAdmin"
    }, m("div", {
      className: "CanelaSystemAdmin-user"
    }, m(Avatar, {
      user: avatarUser
    }), m("strong", null, trans(`${KEY}.assign_bot_created_as`, {
      name: user.displayName
    }))), m("p", {
      className: "helpText"
    }, trans(`${KEY}.assign_bot_help`)), m("div", {
      className: "CanelaSystemAdmin-actions"
    }, m("a", {
      className: "Button",
      href: `${app.forum.attribute('baseUrl')}/u/${user.slug}`,
      target: "_blank",
      rel: "noopener"
    }, trans(`${KEY}.assign_bot_open_profile`))));
  }
  create() {
    this.loading = true;
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/canela/assign-assistant`
    }).then(response => {
      this.created = response.data;
      app.forum.pushAttributes({
        canelaAssistant: response.data
      });
      app.data.settings[SETTING] = String(response.data.id);
    }).catch(() => {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ramon-canela', 'admin/features/assign', AssistantCard);